/*
 * Reader for Offsets.ini. See SymbolsHandler.hpp for the contract.
 *
 * The file is machine generated by SymbolTool.exe and is the only source of
 * kernel addresses and structure offsets the mapper uses, so this parser is
 * written to fail on anything unexpected rather than to guess: a truncated
 * section header or a non numeric value skips that entry instead of throwing.
 */

#include "SymbolsHandler.hpp"
#include <algorithm>
#include <string>
#include <iostream>
#include <fstream>
#include <filesystem>
#include <utility>
#include <vector>

#include "../../Utilities/Utilities.hpp"
#include "../../Utilities/Console.hpp"

namespace
{
	/*
	 * Restores PATH when it goes out of scope.
	 *
	 * ReloadFile has to put the DLLs folder on PATH for the SymbolTool it
	 * spawns, because dbghelp.dll and symsrv.dll live in a subfolder that is not
	 * a default search location. That edit used to be left in place after the
	 * call returned, so every later child process of Mapper.exe inherited a PATH
	 * it never asked for, for the rest of the run. Restoring it here means an
	 * early return cannot leave it behind either.
	 */
	class ScopedPathChange
	{
	public:
		ScopedPathChange() {
			//Heap rather than a 32 KB automatic buffer. The automatic one was
			//live at the same time as an identical buffer in ReloadFile, which put
			//64 KB - and then 128 KB once the second one was counted - on the
			//stack of a function that is also on the path out of the crash
			//handler, where the stack has already been walked once by the time
			//anything is reported.
			std::wstring buffer(kPathBufferChars, L'\0');
			const DWORD length = GetEnvironmentVariableW(L"PATH", buffer.data(), static_cast<DWORD>(buffer.size()));
			//0 is "PATH was not set", which is a legitimate state to restore to.
			//At or above the buffer size is truncation, and restoring that would
			//replace a real PATH with a partial one - so nothing is saved and
			//nothing is restored.
			if (length > 0 && length < buffer.size()) {
				had_value_ = true;
				previous_.assign(buffer.data(), length);
			}
		}

		~ScopedPathChange() {
			if (had_value_)
				SetEnvironmentVariableW(L"PATH", previous_.c_str());
		}

		ScopedPathChange(const ScopedPathChange&) = delete;
		ScopedPathChange& operator=(const ScopedPathChange&) = delete;

	private:
		//The longest PATH this will read. 32 KB is the same bound the buffer
		//this replaced used, so the truncation behaviour is unchanged.
		static constexpr size_t kPathBufferChars = 32768;

		bool had_value_ = false;
		std::wstring previous_;
	};

	//Length of the PATH buffer in ScopedPathChange, in characters. See there.
constexpr size_t kPathBufferChars = 32768;

//Trim ASCII whitespace from both ends. The generator emits no spaces, but a
	//hand edited or regenerated file routinely does, and an untrimmed name is a
	//key nothing will ever look up.
	std::wstring Trim(const std::wstring& text) {
		static const wchar_t* whitespace = L" \t\r\n\f\v";
		const size_t first = text.find_first_not_of(whitespace);
		if (first == std::wstring::npos)
			return L"";
		const size_t last = text.find_last_not_of(whitespace);
		return text.substr(first, last - first + 1);
	}

	/*
	 * Parse one offset value, strictly.
	 *
	 * Strictly is the point. std::stoull(" 0x10", nullptr, 10) skips the leading
	 * space, parses 0, stops at the 'x', throws nothing and reports no error - so
	 * a hex value in a file of decimal ones loaded as offset 0 and looked
	 * correct. The parsed text now has to be the whole value, and a 0x prefix is
	 * honoured rather than parsed as the digit zero followed by garbage.
	 */
	bool ParseOffset(const std::wstring& text, unsigned long long& out) {
		const std::wstring value = Trim(text);
		if (value.empty())
			return false;

		//No sign. An offset in this file is a byte count or an address, both
		//unsigned, and stoull happily accepts "-1" and wraps it to ULLONG_MAX -
		//which then reads as a valid offset until whatever uses it is 2^64 bytes
		//past the start of the kernel. Rejecting the sign here is one character
		//of test rather than a bound at each of the dozen consumers.
		if (value[0] == L'-' || value[0] == L'+')
			return false;

		int base = 10;
		size_t digits = 0;
		if (value.size() > 2 && value[0] == L'0' && (value[1] == L'x' || value[1] == L'X')) {
			base = 16;
			digits = 2;
		}

		try {
			size_t consumed = 0;
			//+0 rather than digits 0: the prefix is already consumed by base 16.
			const unsigned long long parsed = std::stoull(value.c_str() + digits, &consumed, base);
			//Anything left over means the value was not what it looked like.
			if (consumed == 0 || consumed != value.size() - digits)
				return false;
			out = parsed;
			return true;
		}
		catch (const std::exception&) {
			return false;
		}
	}

	/*
	 * Run the offset updater and wait for it.
	 *
	 * CreateProcessW rather than _wsystem: the previous call went through
	 * cmd.exe, which is an unnecessary interpreter between this process and a
	 * path it already holds. Nothing here is attacker controlled, so this is not
	 * closing a privilege escalation, but there is no reason to hand a path to a
	 * shell in order to have it quoted.
	 *
	 * The child inherits stdio, so SymbolTool's report still reaches the console
	 * exactly as it did before.
	 *
	 * The wait is bounded: a tool that hangs would otherwise hang the mapper
	 * before it ever touches the kernel.
	 */
	bool RunSymbolTool(const std::wstring& tool_path, DWORD& exit_code) {
		exit_code = 0;

		//CreateProcessW may modify the command line buffer, so it is given a
		//writable copy. lpApplicationName carries the real path, so the quoted
		//command line is only there for display and argument parsing.
		std::wstring command_line = L"\"" + tool_path + L"\"";

		STARTUPINFOW startup{};
		startup.cb = sizeof(startup);
		PROCESS_INFORMATION process{};

		if (!CreateProcessW(
			tool_path.c_str(),
			command_line.data(),
			nullptr, nullptr, FALSE, 0, nullptr, nullptr,
			&startup, &process)) {
			Log(L"[-] Failed to start the offset updater, error "
				<< Val(static_cast<unsigned long>(GetLastError())) << std::endl);
			return false;
		}

		const DWORD waited = WaitForSingleObject(process.hProcess, 120000);

		if (waited == WAIT_TIMEOUT) {
			Log(L"[-] The offset updater did not finish within 120s; terminating it" << std::endl);
			TerminateProcess(process.hProcess, 1);
			WaitForSingleObject(process.hProcess, INFINITE);
			CloseHandle(process.hThread);
			CloseHandle(process.hProcess);
			exit_code = 1;
			return true; //it did run; the caller still checks exit_code and the file
		}

		DWORD status = 0;
		if (waited != WAIT_OBJECT_0 || !GetExitCodeProcess(process.hProcess, &status)) {
			CloseHandle(process.hThread);
			CloseHandle(process.hProcess);
			return false;
		}

		CloseHandle(process.hThread);
		CloseHandle(process.hProcess);
		exit_code = status;
		return true;
	}
}

bool SymbolsHandler::ReloadFile(const std::wstring& requestedPath, const std::wstring& updater) {
	symbols.clear();

	std::wstring path = requestedPath;

	//Grouped explicitly: the original relied on && binding tighter than ||,
	//which is correct but easy to break while editing.
	const bool usingUpdater = !updater.empty();
	const std::wstring& fileToCheck = usingUpdater ? updater : requestedPath;

	if (!std::filesystem::exists(fileToCheck)) {
		Log(L"[-] Offsets file (" << Val(requestedPath) << L") or updater (" << Val(updater) << L") not found" << std::endl);
		return false;
	}

	if (usingUpdater) {
		//The updater always writes to the default location. The previous file is
		//kept until the new one is in place, so a failed run keeps working
		//offsets instead of leaving nothing behind.
		const std::wstring outputPath = Utilities::GetCurrentAppFolder() + L"\\Offsets.ini";

		//Both symbol libraries live in the DLLs subfolder, which is not a
		//default search location, so it has to be on PATH for the child. The
		//change is scoped to this block and undone on the way out, including on
		//an early return.
		const ScopedPathChange path_restore;

		//GetEnvironmentVariableW returns the required size and leaves the buffer
		//untouched when it is too small, so building a PATH from an unchecked
		//length would silently replace the parent's PATH with just this folder.
		//An unset PATH returns 0 and is the intended case; anything at or above
		//the buffer size means truncation and is left alone.
		const std::wstring dllFolder = Utilities::GetCurrentAppFolder() + L"\\" + SYMBOL_DLL_FOLDER;
		if (std::filesystem::is_directory(dllFolder)) {
			//On the heap rather than in this frame: see kPathBufferChars. The
			//ScopedPathChange above already holds a copy of the value being
			//replaced, so this one only has to survive until SetEnvironmentVariableW
			//has been called.
			std::wstring oldPath(kPathBufferChars, L'\0');
			const DWORD pathLength = GetEnvironmentVariableW(L"PATH", oldPath.data(), static_cast<DWORD>(oldPath.size()));
			if (pathLength == 0 || pathLength >= oldPath.size()) {
				//0 means PATH was unset, which is the intended case; at or above
				//the buffer size means truncation, which is not.
				Log(L"[-] PATH is too long to extend; leaving PATH alone" << std::endl);
			}
			else {
				const std::wstring newPath = dllFolder + L";" + oldPath.substr(0, pathLength);
				SetEnvironmentVariableW(L"PATH", newPath.c_str());
			}
		}

		DWORD exitCode = 0;
		if (!RunSymbolTool(updater, exitCode) || exitCode != 0) {
			Log(L"[-] Failed to update offsets (exit code " << Val(static_cast<unsigned long>(exitCode)) << L")" << std::endl);
			Log(L"[-] Offsets file expected at: " << Val(outputPath) << std::endl);
			return false;
		}

		if (!std::filesystem::exists(outputPath)) {
			Log(L"[-] Updater ran but produced no " << Val(outputPath) << std::endl);
			return false;
		}

		path = outputPath;
	}

	//INI shaped: [section] headers are read for the log only, the entries
	//themselves are a flat name = offset list.
	//load file with ini format
	std::wifstream file(path);
	if (!file.is_open()) {
		Log(L"[-] Failed to open offsets file" << std::endl);
		return false;
	}

	//Lines are buffered and reported in two groups - every symbol, then every
	//structure field - so the console report has the same shape SymbolTool.exe
	//prints instead of interleaving each module's symbols with its own fields.
	//
	//Entries are held structured rather than pre-rendered: the field group is
	//sorted by name below, and a rendered string cannot be sorted against a
	//list of names.
	struct LoadedEntry {
		std::wstring section;
		std::wstring name;
		unsigned long long offset = 0;
	};

	std::vector<LoadedEntry> symbolEntries;
	std::vector<LoadedEntry> fieldEntries;

	std::wstring line;
	std::wstring currentSection;

	//Counted separately so the summary can say what was actually loaded: an
	//Offsets.ini entry is either a symbol (a [<module>] section) or a structure
	//field (a [<module>.fields] section).
	size_t symbolCount = 0;
	size_t fieldCount = 0;

	while (std::getline(file, line)) {
		if (line.empty() || line[0] == L';' || line[0] == L'#') {
			continue;
		}
		if (line[0] == L'[') {
			//A section header needs both brackets; substr would underflow here.
			if (line.back() != L']') {
				Log(L"[-] Malformed section header, skipping" << std::endl);
				continue;
			}
			currentSection = line.substr(1, line.size() - 2);
			continue;
		}
		auto pos = line.find(L'=');
		if (pos == std::wstring::npos) {
			continue;
		}
		auto name = Trim(line.substr(0, pos));
		auto offset = Trim(line.substr(pos + 1));

		if (name.empty()) {
			Log(L"[-] Skipping an entry with no name" << std::endl);
			continue;
		}

		//std::stoull throws on anything that is not a number, which would take
		//the whole mapper down on a malformed offsets file. ParseOffset throws
		//nothing and returns false instead.
		unsigned long long parsed = 0;
		if (!ParseOffset(offset, parsed)) {
			Log(L"[-] Skipping malformed offset for " << Val(name) << std::endl);
			continue;
		}

		const bool isField = currentSection.size() >= 7 &&
			currentSection.compare(currentSection.size() - 7, 7, L".fields") == 0;

		//A duplicate name would silently shadow the earlier entry. The file is
		//machine generated, so a repeat means the generator changed or the file
		//was hand edited, and either way the two values disagree and the later
		//one is being taken on trust.
		const auto [existing, inserted] = symbols.emplace(name, parsed);
		if (!inserted && existing->second != parsed) {
			Log(L"[-] Duplicate entry for " << Val(name) << L" with conflicting offsets ("
				<< Val(Hex(existing->second)) << L" vs " << Val(Hex(parsed)) << L"), keeping the first" << std::endl);
		}

		(isField ? fieldEntries : symbolEntries).push_back({ currentSection, name, parsed });

		if (isField)
			++fieldCount;
		else
			++symbolCount;
	}

	/*
	 * Order the field group reports in.
	 *
	 * Offsets.ini lists fields in the order SymbolTool requested them, which is
	 * the order they appear in the PDB walk rather than the order a reader needs.
	 * This list groups them the way the mapper consumes them - the offsets the
	 * cleanup walks dereference first, then the DRIVER_OBJECT members it writes
	 * for DriverEntry, then the extension members - so a wrong offset stands out
	 * against the structure it belongs to instead of being buried mid-list.
	 *
	 * A field this list does not name keeps its file order and still reports, so a
	 * newly resolved field can never vanish from the report by being absent here.
	 */
	static const std::vector<std::wstring> fieldOrder{
		L"_KLDR_DATA_TABLE_ENTRY.BaseDllName",
		L"_DRIVER_OBJECT.DriverExtension",
		L"_DRIVER_EXTENSION.DriverObject",
		L"_DRIVER_OBJECT.DriverSection",
		L"_DRIVER_OBJECT.DriverUnload",
		L"_DEVICE_OBJECT.DriverObject",
		L"_RTL_AVL_TABLE.DeleteCount",
		L"_DRIVER_OBJECT.DriverStart",
		L"_DRIVER_OBJECT.DriverSize",
		L"_FILE_OBJECT.DeviceObject",
		L"_DRIVER_OBJECT.Flags",
		L"_DRIVER_OBJECT.Size",
	};

	//fieldOrder has static storage duration, so it is visible inside the lambdas
	//below without being captured - naming it in a capture list is an error.
	//rank is hoisted out of the comparator so the lookup is not rebuilt on every
	//comparison, and so the comparator only has to capture rank.
	const auto rank = [](const std::wstring& name) {
		for (size_t i = 0; i < fieldOrder.size(); i++)
			if (fieldOrder[i] == name)
				return i;
		return fieldOrder.size();
	};

	std::stable_sort(fieldEntries.begin(), fieldEntries.end(),
		[&rank](const LoadedEntry& a, const LoadedEntry& b) {
			return rank(a.name) < rank(b.name);
		});

	/*
	 * Order the symbol group reports in, and the separator style it uses.
	 *
	 * The order groups the offsets by what they are for rather than by the
	 * PDB walk order SymbolTool wrote them in: the allocation primitives the
	 * mapper calls, the PiDDBCacheTable it walks, the ci.dll hash bucket cache,
	 * then PiDDBLock, then MmPteBase - the address the read-only write
	 * primitive is built on, which is reported last because it is the last
	 * thing resolved before the first kernel call.
	 *
	 * A symbol this list does not name keeps its file order and still reports,
	 * so a newly resolved symbol can never vanish from the report by being
	 * absent here.
	 *
	 * The "Wrote" line is printed inside this group, between MmPteBase and
	 * g_HashCacheLock. That is not where the updater writes the file - it does
	 * so before the mapper reads it - but the line belongs with the offsets it
	 * produced, and the head of the group is occupied by the offsets that are
	 * consumed first.
	 */
	static const std::vector<std::wstring> symbolOrder{
		L"MmAllocateIndependentPagesEx",
		L"MmFreeIndependentPages",
		L"MmSetPageProtection",
		L"PiDDBCacheTable",
		L"g_KernelHashBucketList",
		L"PiDDBLock",
		L"MmPteBase",
		L"g_HashCacheLock",
	};

	/*
	 * The "Wrote" line belongs immediately before g_HashCacheLock, which is the
	 * last offset the mapper resolves before its first kernel call.
	 *
	 * It used to be a hardcoded index - 7 - into the sorted list, which only
	 * lines up while every symbol above happens to be present. On a machine
	 * without Defender, ci.dll resolves nothing and the list is one shorter, so
	 * the seventh entry was never reached and the line never printed at all. The
	 * position is now found by name, and the line falls back to the end of the
	 * list if that name is missing too, so it always prints.
	 */
	const std::wstring wroteBefore = L"g_HashCacheLock";

	//Rank is hoisted out of the comparator so the lookup is not rebuilt on every
	//comparison, and so the comparator only has to capture rank.
	const auto symbolRank = [](const std::wstring& name) {
		for (size_t i = 0; i < symbolOrder.size(); i++)
			if (symbolOrder[i] == name)
				return i;
		return symbolOrder.size();
	};

	std::stable_sort(symbolEntries.begin(), symbolEntries.end(),
		[&symbolRank](const LoadedEntry& a, const LoadedEntry& b) {
			return symbolRank(a.name) < symbolRank(b.name);
		});

	//Only printed when the updater actually produced the file; with
	//--dontUpdateOffsets nothing was written by this run.
	bool wrote_printed = false;
	for (const auto& entry : symbolEntries) {
		if (usingUpdater && !wrote_printed && entry.name == wroteBefore)
			Log(L"[+] Wrote | " << Val(path) << std::endl), wrote_printed = true;

		Log(L"[+] Loaded " << Val(entry.section) << L" | " << Val(entry.name)
			<< L" | Offset = " << Val(Hex(entry.offset)) << std::endl);
	}
	if (usingUpdater && !wrote_printed) {
		Log(L"[+] Wrote | " << Val(path) << std::endl);
		wrote_printed = true;
	}
	LogBlank();

	for (const auto& entry : fieldEntries)
		Log(L"[+] Loaded " << Val(entry.section) << L" | " << Val(entry.name)
			<< L" | Offset = " << Val(Hex(entry.offset)) << std::endl);
	LogBlank();

	Log(L"[+] Loaded " << Val(symbols.size()) << L" Offsets (" << Val(symbolCount)
		<< L" Symbols, " << Val(fieldCount) << L" Fields) From " << Val(path) << std::endl);
	LogBlank();

	/*
	 * Refuse a file that parsed but describes nothing usable.
	 *
	 * A file with no entries - empty, or every line malformed, or a file of the
	 * wrong kind entirely - used to return true. The summary then printed
	 * "Loaded 0 Offsets" and the run went on to walk kernel structures using the
	 * compiled-in defaults, with the handler reporting success the whole way.
	 * For a file whose entire purpose is that "a wrong or missing entry is the
	 * difference between finding a structure and corrupting one", accepting zero
	 * of them is the one outcome that must not be called success.
	 *
	 * MmPteBase is singled out because it is the one symbol Driver::Load cannot
	 * proceed without on any path: it is the base of the PTE self-map, and
	 * ResolveMmPteBase fails the run when it is absent. Everything else has its
	 * own stage that reports its own missing symbol by name, so requiring all of
	 * them here would refuse runs that legitimately use --no-forensics.
	 */
	static const std::vector<std::wstring> kRequiredEntries{ L"MmPteBase" };

	std::wstring missing;
	for (const auto& required : kRequiredEntries) {
		if (symbols.find(required) == symbols.end()) {
			if (!missing.empty())
				missing += L", ";
			missing += required;
		}
	}

	if (symbols.empty() || !missing.empty()) {
		Log(L"[-] " << Val(path) << L" does not describe this build's offsets"
			<< (missing.empty() ? std::wstring(L" - no entries were parsed")
				: std::wstring(L" - missing: ") + missing)
			<< std::endl);
		Log(L"[-] Refusing to map on compiled-in defaults; run without --dontUpdateOffsets to regenerate it" << std::endl);
		LogBlank();
		symbols.clear();
		return false;
	}

	return true;
}

unsigned long long SymbolsHandler::GetOffset(const std::wstring& name) {
	const auto it = symbols.find(name);
	return it == symbols.end() ? 0 : it->second;
}

//Structure field offsets are stored as "<Struct>.<Field>" entries and are
//unique, so a plain lookup is enough.
unsigned long long SymbolsHandler::GetFieldOffset(const std::wstring& structAndField) {
	const auto it = symbols.find(structAndField);
	return it == symbols.end() ? kFieldUnresolved : it->second;
}
